import test from 'node:test';import assert from 'node:assert/strict';
import {settleCrewSetup,rarePlan,learnAndFitRare,learnAndWearSchool,collectSetupUnlocks,moveSummary} from '../crew-setup-model.js';
import {defaultHero} from '../mako.js';import {availablePoints} from '../skill-grid-model.js';
const state=()=>({chapter:7,scene:228,mode:'field',party:[0],recruited:[0],heroes:Array.from({length:7},(_,id)=>defaultHero(id)),story:{firstCore:true},cores:['earth','mend'],supports:['focus','echo'],items:{},bosses:[],skillGrid:{},kakeya:{version:2,solved:[2],assignments:{},relics:['anchorheart']}});
test('free setup fills only earned empty sockets and never spends growth or changes chosen moves',()=>{const s=state(),h=s.heroes[0];h.unlockedSlots=2;h.loadout=[{core:'mend',support:'echo'}];const points=availablePoints(s,0);assert.equal(settleCrewSetup(s).length,1);assert.deepEqual(h.loadout[0],{core:'mend',support:'echo'});assert.deepEqual(h.loadout[1],{core:'earth',support:'focus'});assert.equal(availablePoints(s,0),points);assert.deepEqual(settleCrewSetup(s),[]);});
test('battle and pre-core onboarding never get automatic equipment changes',()=>{const s=state();s.heroes[0].loadout=[];s.heroes[0].unlockedSlots=2;s.mode='battle';assert.deepEqual(settleCrewSetup(s),[]);s.mode='field';s.story.firstCore=false;assert.deepEqual(settleCrewSetup(s),[]);assert.equal(s.heroes[0].loadout.length,0);});
test('a rare decision buys the exact prerequisite chain and applies its battle effect in one action',()=>{const s=state(),h=s.heroes[0];h.level=5;h.loadout=[{core:'earth',support:'focus'}];const plan=rarePlan(s,0,'anchorheart'),before=availablePoints(s,0);assert.equal(plan.cost,2);assert.equal(learnAndFitRare(s,0,'anchorheart',0),true);assert.equal(availablePoints(s,0),before-2);const t=moveSummary(s,0,0);assert.equal(t.makoId,'anchorheart');assert.equal(t.interrupt,true);const after=availablePoints(s,0);assert.ok(learnAndFitRare(s,0,'anchorheart',0));assert.equal(availablePoints(s,0),after);});
test('unaffordable rare bundles change neither points nor slots',()=>{const s=state();s.kakeya.relics=['mercyglass'];s.heroes[0].level=1;s.chapter=1;const before=JSON.stringify(s);assert.equal(learnAndFitRare(s,0,'mercyglass',0),false);assert.equal(JSON.stringify(s),before);});
test('learned rare traits settle only into compatible unoccupied moves',()=>{const s=state();s.skillGrid[0]=['6:0','mako:anchorheart'];s.heroes[0].loadout=[{core:'mend',support:'focus'},{core:'earth',support:'echo'}];assert.equal(settleCrewSetup(s).length,1);assert.equal(s.heroes[0].loadout[0].makoId,undefined);assert.equal(s.heroes[0].loadout[1].makoId,'anchorheart');assert.deepEqual(settleCrewSetup(s),[]);});
test('school selection learns and equips atomically; a full capacity never burns points',()=>{const s=state();s.heroes[0].level=8;assert.ok(learnAndWearSchool(s,0,'stone'));assert.equal(s.heroes[0].doctrineSlots[0],'stone');assert.ok(moveSummary(s,0,0).doctrines.some(x=>x.id==='stone'));const before=JSON.stringify(s);assert.equal(learnAndWearSchool(s,0,'mercy'),false);assert.equal(JSON.stringify(s),before);assert.ok(learnAndWearSchool(s,0,'road'));});
test('unlock cues batch once, persist across saves, and do not replay for spending or old saves',()=>{const s=state();assert.deepEqual(collectSetupUnlocks(s),[]);s.supports.push('field');s.heroes[0].level=2;const batch=collectSetupUnlocks(s);assert.ok(batch.some(x=>x.includes('Field')));assert.ok(batch.some(x=>x.includes('growth')));assert.deepEqual(collectSetupUnlocks(s),[]);assert.deepEqual(collectSetupUnlocks(JSON.parse(JSON.stringify(s))),[]);s.skillGrid[0]=['0:0'];assert.deepEqual(collectSetupUnlocks(s),[]);});
test('story-learned personal arts connect for free and never need to be bought again',()=>{const s=state(),before=availablePoints(s,0);s.heroes[0].learned|=128;settleCrewSetup(s);assert.ok(s.skillGrid[0].includes('5:0'));assert.ok(s.crewSetup.freeNodes[0].includes('5:0'));assert.equal(availablePoints(s,0),before);settleCrewSetup(s);assert.equal(s.crewSetup.freeNodes[0].filter(x=>x==='5:0').length,1);assert.equal(availablePoints(JSON.parse(JSON.stringify(s)),0),before);});
